from ta5g_delta.operations import *  # noqa: F403
from ta5g_delta.reader import *  # noqa: F403


def create_reverse_dicts(delta, full):
    reverse_dicts = __create_reverse_mocs(delta, full)
    for moc in reverse_dicts:
        for param in __find_param_in_operation(delta, full):
            if moc['operation'] == 'update' and moc['distName'] == param['distName']:
                moc["parameters"].append(param["parameters"])
    return reverse_dicts


def __find_param_in_operation(delta, full):
    for operation in __list_of_param_operations(delta, full):
        for param in operation:
            yield param


def __list_of_param_operations(delta, full):
    return [delete_parameters(delta, full), create_parameters(delta, full), update_parameters(delta, full)]  # noqa: F405


def __list_of_moc_operation(delta, full):
    return [delete_moc(delta, full), create_moc(delta, full), update_moc(delta, full)]  # noqa: F405


def __create_reverse_mocs(delta, full):
    reverse_delta = []
    for operation in __list_of_moc_operation(delta, full):
        for moc in operation:
            reverse_delta.append(moc)
    return reverse_delta
